-- ============================================
-- INFORME_AUDITORIA: bitácora de acciones sobre los informes (trazabilidad)
-- ACCION: CREAR, EDITAR, SUBIR_ARCHIVO, DESCARGAR, ANULAR
-- ============================================
CREATE TABLE IF NOT EXISTS "INFORME_AUDITORIA" (
    "ID_AUDITORIA" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_INFORME_AUDITORIA" PRIMARY KEY,
    "ID_INFORME" INT NOT NULL CONSTRAINT "FK_INFORME_AUDITORIA_INFORME" REFERENCES "INFORMES" ("ID_INFORME"),
    "ID_USUARIO" INT NULL CONSTRAINT "FK_INFORME_AUDITORIA_USUARIO" REFERENCES "USUARIOS" ("ID_USUARIO"),
    "ACCION" VARCHAR(30) NOT NULL,
    "DETALLE" VARCHAR(1000) NULL,
    "IP" VARCHAR(64) NULL,
    "FECHA" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS "IX_INFORME_AUDITORIA_INFORME" ON "INFORME_AUDITORIA" ("ID_INFORME", "FECHA");
